   const { Client, Intents } = require('discord.js');

   const client = new Client({
     intents: [
       Intents.FLAGS.GUILDS,
       Intents.FLAGS.GUILD_MESSAGES,
     ],
   });

   client.on('ready', () => {
     console.log(`Bot ${client.user.tag} is online!`);
   });
   ```

5. Fügen Sie folgendes Code hinzu, um den `ban`-Befehl zu implementieren:

   ```javascript
   const { Message, Permissions } = require('discord.js');

   client.on('messageCreate', async (message) => {
     if (!message.guild || message.author.id === client.user.id) return;

     if (message.content.startsWith('ban ')) {
       const member = message.mentions.members.first();
       if (!member) {
         return message.reply('Bitte nenne einen Benutzer, den du bannen willst!');
       }

       if (!message.member.permissions.has(Permissions.FLAGS.BAN_MEMBERS)) {
         return message.reply('Du hast keine Berechtigung, diesen Benutzer zu bannen!');
       }

       if (member.permissions.has(Permissions.FLAGS.ADMINISTRATOR)) {
         return message.reply('Du kannst Administratoren nicht bannen!');
       }

       await member.ban();
       message.reply(`Der Benutzer ${member.user.tag} wurde gebannt!`);
     }
   });
   ```

