Hier ist ein Beispiel C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main() {
    // Einlesen des Suchworts
    string searchWord;
    cout << "Bitte das Suchwort eingeben: ";
    cin >> searchWord;

    // Öffnen der Textdatei
    string fileName;
    cout << "Bitte den Dateinamen eingeben: ";
    cin >> fileName;

    ifstream inputFile(fileName);

    if (!inputFile) {
        cerr << "Fehler beim Öffnen der Datei: " << fileName << endl;
        return 1;
    }

    // Zähler für das Suchwort
    unordered_map<string, int> wordCount;

    // Lese Zeile für Zeile aus der Datei
    string line;
    while (getline(inputFile, line)) {
        // Trenne die Zeile in einzelne Wörter
        istringstream ss(line);
        string word;
        while (ss >> word) {
            // Zähle das Suchwort
            if (word == searchWord) {
                wordCount[searchWord]++;
            }
        }
    }

    // Schließe die Datei
    inputFile.close();

    // Ausgabe des Ergebnisses
    if (wordCount[searchWord] > 0) {
        cout << "Das Suchwort '" << searchWord << "' tritt " << wordCount[searchWord] << " mal in der Datei '" << fileName << "' auf." << endl;
    } else {
        cout << "Das Suchwort '" << searchWord << "' wurde in der Datei '" << fileName << "' nicht gefunden." << endl;
    }

    return 0;
}
```

Dieses Programm erfordert folgende Schritte:

1. Einlesen des Suchworts vom Benutzer
2. Einlesen des Dateinamens vom Benutzer
3. Öffnen der Textdatei
4. Erstellen eines unsortierten Hashtables (unordered_map) zum Zählen der Vorkommen des Suchworts
